/*
 * Stands in for `react-native-worklets/plugin`, doing the one thing that design this
 * covers cannot work without: flipping the `false` literal of
 * `_WORKLETS_BUNDLE_MODE_ENABLED = false` to `true` when `bundleMode: true`.
 *
 * That flip is compile-time work, so it only happens for files the app's JS rule
 * actually transforms - which is exactly the coupling worth protecting with a test.
 * Without it `globalThis._WORKLETS_BUNDLE_MODE_ENABLED` stays false and every
 * Worklets guard remains armed, no matter what the bundler does.
 *
 * Workletization is not reproduced: the fixture imports a checked-in
 * `.worklets/<hash>.js` factory directly, which is the same request the real plugin
 * emits, so the module graph is identical without depending on the real plugin.
 */

module.exports = function workletsFixtureBabelPlugin({ types: t }) {
  return {
    name: 'babel-plugin-worklets-fixture',
    visitor: {
      AssignmentExpression(path, state) {
        if (state.opts && state.opts.bundleMode === true) {
          const { left, right } = path.node;
          if (
            left.type === 'MemberExpression' &&
            left.object.type === 'Identifier' &&
            left.object.name === 'globalThis' &&
            left.property.type === 'Identifier' &&
            left.property.name === '_WORKLETS_BUNDLE_MODE_ENABLED' &&
            right.type === 'BooleanLiteral' &&
            right.value === false
          ) {
            path.node.right = t.booleanLiteral(true);
          }
        }
      },
    },
  };
};
